def wrap(phi):
    return (phi + np.pi) % (2 * np.pi) - np.pi

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--show", "-s", action="store_true", help="保存后显示交互窗口")
    args = parser.parse_args()
    if not args.show:
        matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    for epc, type in target_epc.items():
        mat = np.asarray(data[epc], dtype=np.float64)
        assert mat.ndim == 3 and mat.shape[-1] == 2
        powers = mat[:, :, 0]
        phases = mat[:, :, 1]
        itp_idx = np.argmax(~np.isnan(phases), axis=1)
        itps = powers[np.arange(powers.shape[0]), itp_idx]
        kais = powers - itps[:, np.newaxis]
        phase_distortions = phases - phases[np.arange(phases.shape[0]), itp_idx][:, np.newaxis]
        phase_distortions = np.angle(np.exp(1j * phase_distortions))


        reference_kais = kais[0, :]
        reference_distortions = phase_distortions[0, :]
        other_kais = kais[1:, :]
        other_distortions = phase_distortions[1:, :]

        mask = ~np.isnan(reference_distortions)
        x_valid = reference_kais[mask]
        y_valid = reference_distortions[mask]
        k, b = np.polyfit(x_valid, y_valid, deg=1)

        # if type == "Higgs3":
        #     phase_errors = other_distortions - k * other_kais
        # else:
        #     phase_errors = other_distortions - reference_distortions
        phase_errors = other_distortions - k * other_kais

        phase_errors = np.angle(np.exp(1j * phase_errors))

        # # 按发射功率 Ptx 分组的误差平均值和标准差
        # mean = np.nanmean(phase_errors, axis=0)
        # std = np.nanstd(phase_errors, axis=0, ddof=1)
        # xs = powers[0]

        # 按 Ptx - ITP = kai 分组的误差平均值和标准差
        other_kais_flat = other_kais.ravel()
        phase_errors_flat = phase_errors.ravel()
        xs = np.unique(other_kais_flat)
        xs = xs[xs >= 0]
        mean = np.zeros(len(xs))
        std = np.zeros(len(xs))
        for i, val in enumerate(xs):
            mask = (other_kais_flat == val)
            vals = phase_errors_flat[mask]
            mean[i] = np.nanmean(vals)
            std[i] = np.nanstd(vals, ddof=1)


        with plt.rc_context(STYLE):
            fig, ax = plt.subplots()
            # 直接绘制原始值：np.nan 自动断线，不插值、不平滑。
            # 只有一组测量数据，不能据此构造标准差或置信区间阴影。
            ax.plot(xs, mean, color="#1f77b4", linewidth=3)
            ax.fill_between(xs, mean - std, mean + std,
                    color="#1f77b4", alpha=0.25)

            # # 按发射功率 Ptx 分组的误差平均值和标准差
            # ax.set_xlabel("Transmit Power (dBm)")
            # ax.set_ylabel("Phase Error (rad)")
            # ax.set_xlim(15, 32)
            # ax.set_ylim(-0.2, 0.2)
            # ax.set_xticks(np.arange(16, 32.5, 2))
            # ax.set_yticks(np.arange(-0.2, 0.2, 0.1))

            # 按 Ptx - ITP = kai 分组的误差平均值和标准差
            ax.set_xlabel(r"$\chi$ (dB)")
            ax.set_ylabel("Phase Error (rad)")
            ax.set_xlim(0, 22)
            ax.set_ylim(-0.2, 0.2)
            ax.set_xticks(np.arange(0, 22.5, 2))
            ax.set_yticks(np.arange(-0.2, 0.2, 0.1))

            ax.grid(True)
            # 单条曲线不需要频率图例；图号和图注由论文排版统一添加。
            fig.tight_layout()
            tag_dir = OUTPUT_DIR / epc
            tag_dir.mkdir(parents=True, exist_ok=True)
            for suffix in ("pdf",):
                path = tag_dir / f"phase_correction_error_kai_{type}_new.{suffix}"
                fig.savefig(path, dpi=600, facecolor="white")
                print(f"Saved: {path}")
            # print(f"Valid measurements: {np.isfinite(phase).sum()} / {len(phase)}")
            if args.show:
                plt.show()
            plt.close(fig)



if __name__ == "__main__":
    main()
